import{_ as s,l,o as a,c as i,v as t,p as d,x as o,d as u,i as n,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"tasklet 与 workqueue","description":"","frontmatter":{"title":"tasklet 与 workqueue","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/tasklet-workqueue.md","filePath":"cs/tasklet-workqueue.md","lastUpdated":1789023840000}'),k={name:"cs/tasklet-workqueue.md"};function p(h,e,_,q,m,A){const r=l("Mermaid");return a(),i("div",null,[e[1]||(e[1]=t('<h1 id="tasklet-与-workqueue" tabindex="-1">tasklet 与 workqueue <a class="header-anchor" href="#tasklet-与-workqueue" aria-label="Permalink to &quot;tasklet 与 workqueue&quot;">​</a></h1><div class="epigraph"><p>同一条下半部纪律下，还要再分：仍禁睡眠的串行小函数，以及跑在内核线程里、可以阻塞的工作项。</p><footer>—— 据 Love, Linux Kernel Development；Bovet and Cesati 整理</footer></div><p><a href="/cs/hardirq-softirq">上一课</a>给出硬/软两档上下文，软中断仍不能睡。网卡协议之后若还要分配可睡的内存、要等文件系统，软中断会拖死返回路径。缺口是两种排队对象：<strong>tasklet</strong>（或同类：软中断里串行执行、禁睡眠）与 <strong>workqueue</strong>（内核工作线程上跑、可睡眠）。本课只钉这一分档，不写框架的全部 API。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软中断类型少、全局 pending 位粗。驱动需要「就这块缓冲、稍后再算」而不占用一种软中断号。tasklet 把函数指针挂进每 CPU 队列，在软中断点串行跑完——仍禁睡眠，但比新注册一种软中断轻。真正要 <code>mutex_lock</code>、要拷用户页，必须换到进程上下文：workqueue 把工作项交给 <code>kworker</code> 一类线程，调度器可见。缺口是这套分流，不是新的设备 IRQ 硬件。</p><p><span class="marginnote">同一 tasklet 在单 CPU 上不重入；能否在多 CPU 上并行，实现有「一次一个」的变体。workqueue 可以并发，提交者必须自己保护共享数据。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>ISR 或软中断：<code>tasklet_schedule</code> 把后续函数入队；或 <code>queue_work</code> 把项交给工作队列。tasklet 在软中断里执行；work 在线程里执行，可调用<a href="/cs/syscall-path">系统调用路径</a>同款的可睡函数（自己就是内核线程）。禁止在硬 IRQ 里直接睡，这条不变。</p>',8)),(a(),d(c,null,{default:o(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20ISR%5B%22%E7%A1%AC%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20TL%5B%22tasklet%3A%20%E7%A6%81%E7%9D%A1%E3%80%81%E8%BD%AF%E4%B8%AD%E6%96%AD%E7%82%B9%22%5D%0A%20%20ISR%20--%3E%20WQ%5B%22workqueue%3A%20%E5%8F%AF%E7%9D%A1%E3%80%81%E7%BA%BF%E7%A8%8B%22%5D%0A%20%20WQ%20--%3E%20SCH%5B%22%E8%BF%9B%E5%85%A5%E8%B0%83%E5%BA%A6%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[u(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>选择标准：要不要睡、要不要与特定进程的地址空间绑在一起。绑定用户缓冲的工作往往要在发起 <code>read</code> 的那个进程上下文做，那是线程化中断的后话。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分流让<a href="/cs/scheduling-metrics">调度指标</a>里的延迟可解释：tasklet 仍增加软中断尾延迟；work 的延迟是调度延迟，可能被公平调度器摊薄。上半部与这两类队列之间的描述符仍是共享数据，后课的锁要标明「持锁者能否睡」。</p><p>不要把 workqueue 当成用户进程：它没有用户 trapframe，但有内核栈与调度实体。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 Linux 工作队列的 <code>WQ_HIGHPRI</code>、绑核属性写成运维手册。也不把 tasklet 的弃用时间线当主干：对象是「禁睡回调 vs 可睡线程」，名字可以换。threaded IRQ 是下一课。</p><p>后课默认：可睡工作进线程。若希望整条 IRQ 处理都是可调度、可设优先级的线程，下一课讲中断线程化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>tasklet：软中断点上的禁睡回调；workqueue：可睡的内核线程工作项。</li><li>硬 IRQ 里仍然不能睡眠。</li><li>把 IRQ 整条做成线程是下一课。</li><li>出处：Love, <em>LKD</em>；Bovet and Cesati。</li></ul>',9))])}const w=s(k,[["render",p]]);export{f as __pageData,w as default};
